using System;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing NUnit.Framework;\nusing Serilog;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n\n        public PetSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [When(\"I send a POST request with the following data:\")]\n        public void WhenISendAPostRequestWithTheFollowingData(Table table)\n        {\n            try\n            {\n                var pet = new Pet\n                {\n                    Id = int.Parse(table.Rows[0][\"id\"]),\n                    Name = table.Rows[0][\"name\"],\n                    Status = table.Rows[0][\"status\"]\n                };\n                var response = _petApiHelper.SendPostRequest(pet);\n                _scenarioContext[\"response\"] = response;\n                Log.Information(\"POST request sent successfully.\");\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error sending POST request.\");\n                Assert.Fail(\"POST request failed.\");\n            }\n        }\n\n        [When(\"I send a GET request for pet with ID {int}\")]\n        public void WhenISendAGetRequestForPetWithId(int id)\n        {\n            try\n            {\n                var response = _petApiHelper.SendGetRequest(id);\n                _scenarioContext[\"response\"] = response;\n                Log.Information(\"GET request sent successfully.\");\n            }\n            catch (Exception ex)\n            {\n                Log.Error(ex, \"Error sending GET request.\");\n                Assert.Fail(\"GET request failed.\");\n            }\n        }\n\n        [When(\"I send a PUT request to update pet with ID {int} to status {string